//! Conformance tests for the shared pragma-configured connection opener.
//!
//! Every bead-rs code path that touches a workspace database -- the store
//! itself, the command handlers in the binary, and the doctor diagnostics --
//! opens through `bead_rs::store::open_configured_connection` (the handlers
//! reach it via `store::open_configured_connection` in main.rs and doctor.rs;
//! a repo-wide grep for raw `Connection::open` outside the helper guards
//! that routing). Both `foreign_keys` and `busy_timeout` are per-connection
//! SQLite defaults (OFF and 0), so the pragma configuration is observable
//! behavior, not an implementation detail: without it, the migrations'
//! `ON DELETE CASCADE` rules go unenforced and concurrent fleet access
//! fails immediately with `SQLITE_BUSY` instead of waiting out the other
//! writer.

use assert_cmd::Command;
use std::time::{Duration, Instant};
use tempfile::TempDir;

fn create_workspace() -> TempDir {
    let temp_dir = TempDir::new().unwrap();

    Command::cargo_bin("bead")
        .unwrap()
        .args(["init", "--prefix", "bead"])
        .current_dir(temp_dir.path())
        .assert()
        .success();

    temp_dir
}

/// The shared opener every handler uses must configure the connection the
/// way `SqliteStore` configures its own: `foreign_keys = ON` (1) and
/// `busy_timeout = 5000`, plus the WAL journal and `synchronous = NORMAL`
/// (1) the store relies on.
#[test]
fn test_open_configured_connection_applies_store_pragmas() {
    let temp_dir = create_workspace();
    let db_path = temp_dir.path().join(".beads/beads.db");

    let conn = bead_rs::store::open_configured_connection(&db_path).unwrap();

    let foreign_keys: i64 = conn
        .query_row("PRAGMA foreign_keys;", [], |row| row.get(0))
        .unwrap();
    assert_eq!(foreign_keys, 1, "foreign_keys must be ON");

    let busy_timeout: i64 = conn
        .query_row("PRAGMA busy_timeout;", [], |row| row.get(0))
        .unwrap();
    assert_eq!(busy_timeout, 5000, "busy_timeout must be 5000ms");

    let journal_mode: String = conn
        .query_row("PRAGMA journal_mode;", [], |row| row.get(0))
        .unwrap();
    assert_eq!(journal_mode, "wal", "journal_mode must be WAL");

    let synchronous: i64 = conn
        .query_row("PRAGMA synchronous;", [], |row| row.get(0))
        .unwrap();
    assert_eq!(synchronous, 1, "synchronous must be NORMAL (1)");
}

/// A representative mutating handler (`bead create`, the fleet's core
/// write path) must wait out a concurrent writer instead of failing
/// immediately with `SQLITE_BUSY`. Holds an exclusive write lock from this
/// process for 3s while the handler runs: with the shared opener's
/// `busy_timeout = 5000` the handler blocks until the lock releases and
/// then succeeds; with a raw unconfigured connection it would exit with
/// "database is locked" in well under the lock hold time.
#[test]
fn test_create_handler_waits_for_concurrent_writer() {
    let temp_dir = create_workspace();
    let db_path = temp_dir.path().join(".beads/beads.db");

    // Hold the write lock from a second connection. In WAL mode this
    // blocks other writers (the handler's INSERT) but not readers, so the
    // handler's own pre-write reads still succeed and the wait lands
    // exactly on the write the timeout exists to protect.
    let holder = bead_rs::store::open_configured_connection(&db_path).unwrap();
    holder.execute("BEGIN EXCLUSIVE", []).unwrap();
    holder
        .execute("INSERT INTO checkpoint_state (id) VALUES (1) ON CONFLICT DO NOTHING", [])
        .unwrap();

    let start = Instant::now();
    let spawn = std::thread::spawn(|| {
        Command::cargo_bin("bead")
            .unwrap()
            .args([
                "create",
                "--no-auto-flush",
                "--title",
                "Created under a held write lock",
            ])
            .current_dir(temp_dir_path())
            .assert()
            .success();
    });

    std::thread::sleep(Duration::from_secs(3));
    holder.execute("COMMIT", []).unwrap();
    drop(holder);

    spawn.join().unwrap();
    let elapsed = start.elapsed();
    assert!(
        elapsed >= Duration::from_secs(2),
        "create must have waited for the 3s lock hold, took {elapsed:?}"
    );
}

/// The current-directory handle the spawned handler needs. The workspace
/// temp dir is owned by the test thread, so the lock-holding/spawning
/// sequence above moves it here for the child process's cwd.
static TEST_DIR: std::sync::OnceLock<PathBufStatic> = std::sync::OnceLock::new();
type PathBufStatic = std::path::PathBuf;

fn temp_dir_path() -> std::path::PathBuf {
    TEST_DIR.get().expect("test dir not set").clone()
}

